from pathlib import Path
import base64,copy,hashlib,io,json,zipfile
ROOT=Path.cwd();OLD=ROOT/'英文小论文/code/warm_stem_prototype_20261011_v1';NEW=ROOT/'英文小论文/code/warm_stem_prototype_20261011_v2'
OUT=ROOT/'outputs/warm_stem_prototype_20261011_v1'
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
read=lambda p:json.loads(Path(p).read_bytes())
def write(p,x):
 with Path(p).open('x',encoding='utf8') as f:json.dump(x,f,indent=2)
inputs=json.loads(r'''{"1":{"base64":"","sha256":"dce9915a7591f944ecfa3a6c34f8e5ecde9220b740bc214539752cb9c5a475b6","bytes":1623},"2":{"base64":"","sha256":"c4ef83462320f667d914423b05ee59c270a1eebc38ff64a273b99dcbfa46e759","bytes":1623}}''');probe_input=json.loads(r'''{"base64":"","sha256":"d02301b8b25980512e702c68377f75691c817afb16e9e2bf86e461d3cbc59d7a","bytes":2279}''')
assert not OUT.exists() and not NEW.exists()
records={};raws={}
for seed in (1,2):
 d=inputs[str(seed)];b=base64.b64decode(d['base64'],validate=True)
 assert len(b)==d['bytes'] and hashlib.sha256(b).hexdigest()==d['sha256']
 o=json.loads(b);assert o['seed']==seed and o['exit_code']==1 and not o['training_launched']
 assert o['code_sha256']==read(OLD/'protocol.json')['files_sha256']|{'protocol.json':sha(OLD/'protocol.json')}
 assert 'Common-init loading omitted original tensors' in o['error_tail']
 records[str(seed)]=o;raws[seed]=b
d=probe_input;b=base64.b64decode(d['base64'],validate=True)
assert len(b)==d['bytes'] and hashlib.sha256(b).hexdigest()==d['sha256'];o=json.loads(b)
assert o['all794_original_tensors_exact'] and o['all_unlisted_are_zero_BN_counters']
assert not o['missing_original_mapped_keys'] and not o['unexpected']
assert o['expected_new_state_count']==78 and o['actual_missing_keys_count']==68 and len(o['unlisted_new_state_keys'])==10
assert o['batchnorm_loader_source_sha256']==hashlib.sha256(o['batchnorm_loader_source'].encode()).hexdigest()
assert o['model_forwards']==o['training_epochs']==0 and not o['CUDA_initialized']
OUT.mkdir()
for seed in (1,2):
 with (OUT/f'remote_CPU_execution_seed{seed}_v1.json').open('xb') as f:f.write(raws[seed])
with (OUT/'load_probe_seed1_v1.json').open('xb') as f:f.write(b)
write(OUT/'transport_verification_v1.json',dict(status='PASS_REMOTE_CPU_FAILURE_AND_PROBE_LENGTH_SHA256',executions=inputs,probe=probe_input))
write(OUT/'execution_state_v1.json',dict(status='CPU_LOADING_CHECK_FALSE_REJECTION_NO_TRAINING',
 goal_complete=False,training_launched=False,training_epochs=0,detector_forwards=0,
 reason='PyTorch2.5.1 BatchNorm compatibility fills10 new num_batches_tracked buffers without listing them as missing. The expectation of78 missing entries was false;68 are listed. Exact source probe confirms all794 original tensors unchanged on seed1.',
 next='v2 explicitly includes all78 initialized new states alongside all794 remapped original states and uses strict=True; preserve v1 failure, validate v2 before any training.'))
NEW.mkdir()
for p in OLD.iterdir():
 if p.is_file() and p.name!='protocol.json':(NEW/p.name).write_bytes(p.read_bytes())
file=NEW/'initialization.py';s=file.read_text(encoding='utf8')
old="""    loaded=model.load_state_dict(mapped,strict=False)
    if set(loaded.missing_keys)!=extra or loaded.unexpected_keys:
        raise ValueError('Common-init loading omitted original tensors')
    after=model.state_dict()
"""
new="""    # Include every newly initialized parameter/buffer explicitly. This avoids
    # relying on BatchNorm's legacy num_batches_tracked default insertion.
    new_initial={n:current[n].clone() for n in extra}
    complete=dict(mapped);complete.update(new_initial)
    loaded=model.load_state_dict(complete,strict=True)
    if loaded.missing_keys or loaded.unexpected_keys:
        raise ValueError('Strict common-init loading omitted tensors')
    after=model.state_dict()
    if not all(torch.equal(after[n],v) for n,v in new_initial.items()):
        raise ValueError('New branch initialization changed during loading')
"""
assert s.count(old)==1;s=s.replace(old,new)
s=s.replace("native_initialization_retained=True)","native_initialization_retained=True,strict_complete_state_loading=True,\n                new_initialized_states_preserved=len(new_initial))")
file.write_text(s,encoding='utf8')
protocol=copy.deepcopy(read(OLD/'protocol.json'))
protocol.update(schema='warm_stem_engineering_prototype_v2',supersedes='warm_stem_prototype_20261011_v1',
 files_sha256={p.name:sha(p) for p in NEW.iterdir() if p.is_file()},
 loading_repair='All794 original states remapped exactly, all78 new default states included explicitly, strict full state loading; no mask relaxation or original-state omission.',
 prior_failure_evidence='outputs/warm_stem_prototype_20261011_v1/execution_state_v1.json')
write(NEW/'protocol.json',protocol)
buf=io.BytesIO()
with zipfile.ZipFile(buf,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
 for p in sorted(NEW.iterdir()):z.writestr(p.name,p.read_bytes())
raw=buf.getvalue()
print(json.dumps(dict(archive_base64=base64.b64encode(raw).decode(),archive_sha256=hashlib.sha256(raw).hexdigest(),
 archive_bytes=len(raw),files=protocol['files_sha256']|{'protocol.json':sha(NEW/'protocol.json')})))

